    factory<LoadUserFeedUseCase> {
        GetSmartUserFeedUseCase(
            userRepository = get(),
            userCacheDataSource = get(),
            clock = get(),
        )
    }
    factory { params ->
        UserFeedViewModel(
            loadUserFeed = get(),
            scope = params.get<CoroutineScope>(),
            clock = get(),
        )
    }
}

